// Emit the 'new-window' event with the referrer of the page that requested the
// new window. Listeners can forward this referrer to the newly created window
// so that the correct `Referer` header is sent to the server. The constructed
// referrer object is returned so callers can reuse it when loading the new
// window's URL.
WebContents.prototype._emitNewWindowEvent = function (event, url, frameName, disposition, options, additionalFeatures) {
  const referrer = {
    url: this.getURL(),
    policy: 'no-referrer-when-downgrade'
  }
  this.emit('new-window', event, url, frameName, disposition, options, additionalFeatures, referrer)
  return referrer
}

